/**
 * Throws if any key in columns isn't a real, allowlisted column for table.
 * Call this immediately before building any SET clause or INSERT column
 * list from client-supplied data -- this is the actual security boundary,
 * not just documentation.
 */
export function assertColumnsAllowed(table: string, columns: string[]): void {
  const allowed = TABLE_COLUMNS[table];
  if (!allowed) {
    throw new Error(`No column allowlist configured for table "${table}".`);
  }
  for (const c of columns) {
    if (!allowed.has(c)) {
      throw new Error(`Column "${c}" is not allowed for table "${table}".`);
    }
  }
}
